module mnist_npu_top(input wire clk,input wire rst,input wire start,input wire signed [7:0] pixel_in,input wire pixel_we,input wire [9:0] pixel_addr,output wire busy,output wire done,output wire [3:0] predicted_digit); wire signed [7:0] pixel_mem_out; wire [9:0] feature_index; wire [1:0] class_group; input_buffer input_mem(.clk(clk),.rst(rst),.we(pixel_we),.addr(pixel_addr),.din(pixel_in),.dout(pixel_mem_out)); npu_controller controller(.clk(clk),.rst(rst),.start(start),.busy(busy),.done(done),.feature_index(feature_index),.class_group(class_group)); assign predicted_digit=4'd0; endmodule
